$('#main').addEventListener('input',e=>{if(e.target.id==='incident-search'){state.query=e.target.value;renderSearchPreserving('incident-search')}if(e.target.id==='feed-search'){state.feedQuery=e.target.value;renderSearchPreserving('feed-search')}});
