document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.nav){go(b.dataset.nav);return}if(b.dataset.select){state.selected=b.dataset.select;if(state.view==='favorites')go('incidents');else render();if(innerWidth<801)$('.detail')?.scrollIntoView({behavior:'smooth'});return}if(b.dataset.save){const id=b.dataset.save;state.favorites.has(id)?state.favorites.delete(id):state.favorites.add(id);save('favorites',[...state.favorites]);render();return}if(b.dataset.feedSave){const id=b.dataset.feedSave;state.feedFavorites.has(id)?state.feedFavorites.delete(id):state.feedFavorites.add(id);save('feedFavorites',[...state.feedFavorites]);render();return}if(b.dataset.mapMode){if(OFFLINE&&!['schematic','parcel'].includes(b.dataset.mapMode)){toast('Street and satellite layers require the online edition.');return}state.mapMode=b.dataset.mapMode;render();return}if(b.dataset.editFeed!==undefined){editFeed(b.dataset.editFeed);return}if(b.dataset.playFeed){if(OFFLINE){toast('Network feeds are disabled. Import a recording for offline playback.');return}const f=data.feeds.find(x=>x.id===b.dataset.playFeed);if(!f?.streamUrl){editFeed(f?.id);return}playURL(f.streamUrl,f.name,'feed',f.id);return}if(b.dataset.playCall){playCall(b.dataset.playCall);return}if(b.dataset.incidentAudio){playIncident(b.dataset.incidentAudio);return}if(b.dataset.stationIncident){state.selected=b.dataset.stationIncident;go('station');return}if(b.dataset.callMode){state.callMode=b.dataset.callMode;render();return}if(b.dataset.hold){state.held=state.held===b.dataset.hold?null:b.dataset.hold;render();return}if(b.dataset.ignore){const feedId=b.dataset.ignore;state.ignored.add(feedId);const currentCall=data.calls.find(c=>c.id===state.selectedCall);if((audioCurrent?.kind==='feed'&&audioCurrent.id===feedId)||(currentCall?.feedId===feedId&&['call','speech'].includes(audioCurrent?.kind))){stopAudio();audioCurrent=null;$('#mini-player').classList.add('hidden')}render();toast('Talkgroup ignored for this session. Use Release / restore all to restore it.');return}if(b.dataset.ack){state.acknowledged.add(b.dataset.ack);save('acknowledged',[...state.acknowledged]);render();return}if(b.dataset.removeAlert!==undefined){state.alerts.splice(Number(b.dataset.removeAlert),1);save('alerts',state.alerts);render();return}
const action=b.dataset.action;switch(action){case'categories':categoriesModal();break;case'close-modal':$('#modal').close();break;case'clear-types':$('#modal').querySelectorAll('input[type=checkbox]').forEach(x=>x.checked=false);break;case'apply-types':state.types=[...$('#modal').querySelectorAll('[data-type]:checked')].map(x=>x.dataset.type);save('types',state.types);$('#modal').close();render();break;case'add-feed':editFeed();break;case'calls':go('favorites');break;case'release':state.held=null;state.ignored.clear();render();break;case'show-station':go('station');break;case'station-all':state.stationUnit='all';render();break;case'fullscreen':toggleFullscreen();break;case'test-alert':testAlert();break;case'more':state.limit+=100;render();break;case'export':exportWorkspace();break;case'import':$('#import-file').click();break;case'geo-import':$('#geo-file').click();break;case'geo-clear':state.geojson=null;save('geojson',null);render();break;case'local-audio':$('#audio-file').click();break;case'demo':modal('Load training workspace',`<p class="modal-copy">This replaces the incident, feed, and call lists on this device with fictional examples. Export your current workspace first if you want to keep it.</p>`,`<div class="modal-footer"><button data-action="export">Export backup</button><button class="primary" data-action="confirm-demo">Load examples</button></div>`);break;case'confirm-demo':invalidatePoll();data=C.validateImport(D);state.sourceMode='demo';state.lastSync=null;state.settings.endpoint='';save('settings',state.settings);clearInterval(pollTimer);sourceError='';state.selected=data.incidents[0]?.id;persistData();$('#modal').close();render();break;case'disconnect':invalidatePoll();state.settings.endpoint='';save('settings',state.settings);clearInterval(pollTimer);state.sourceMode='saved';sourceError='';persistData();render();break;case'refresh':poll();break;case'dashboard':modal('Save dashboard',`<form id="dashboard-form" class="modal-content stack" style="padding-top:24px"><label>Dashboard name<input name="name" required maxlength="80" placeholder="Newark fire & EMS"></label><button class="primary" type="submit">Save current filters</button></form>`);break;case'enable-notifications':if(!('Notification'in window)){toast('Browser notifications are unavailable here.');break}const permission=await Notification.requestPermission();toast('Notification permission: '+permission);break;case'save-alert':if(state.alerts.length>=100){toast('The workspace supports up to 100 alert rules.');break}state.alerts.push({name:'Incident rule '+(state.alerts.length+1),types:[...state.types],area:state.area,priority:state.priority,query:state.query});save('alerts',state.alerts);render();break;case'candidate':try{$('#candidate-output').textContent=JSON.stringify(C.transcriptCandidate($('#candidate-text').value),null,2)}catch(err){toast(err.message)}break;}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.category){const cat=D.categories.find(c=>c.id===t.dataset.category);cat.types.forEach(x=>{const cb=$('#modal').querySelector(`[data-type="${x.id}"]`);cb.checked=t.checked})}if(t.dataset.type){const cat=D.categories.find(c=>c.types.some(x=>x.id===t.dataset.type));const cb=$('#modal').querySelector(`[data-category="${cat.id}"]`);cb.checked=cat.types.every(x=>$('#modal').querySelector(`[data-type="${x.id}"]`).checked)}if(t.id==='area-filter'){state.area=t.value;render()}if(t.id==='priority-filter'){state.priority=t.value;render()}if(t.id==='station-unit'){state.stationUnit=t.value;render()}if(t.id==='station-incident'){state.selected=t.value;render()}if(t.id==='dashboard-select'&&t.value!==''){Object.assign(state,copy(state.dashboards[Number(t.value)].filters));render()}if(['large-text','show-transcripts','continue-audio','station-sound'].includes(t.id)){const key={'large-text':'largeText','show-transcripts':'transcripts','continue-audio':'continueAudio','station-sound':'stationSound'}[t.id];state.settings[key]=t.checked;save('settings',state.settings);applySettings()}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,fd=new FormData(form);try{if(form.id==='feed-form'){const old=data.feeds.find(f=>f.id===form.dataset.id);const f=C.normalizeFeed({...old,id:old?.id||'feed-'+Date.now(),name:fd.get('name'),area:fd.get('area'),kind:old?.kind||'Public safety',description:'User configured audio source.',streamUrl:fd.get('url')||null,demo:false});data.feeds=C.mergeById(data.feeds,[f]);persistData();$('#modal').close();render();toast('Feed saved. Select Listen to test playback.')}if(form.id==='dashboard-form'){if(state.dashboards.length>=100)throw Error('The workspace supports up to 100 dashboards.');state.dashboards.push({name:String(fd.get('name')).trim(),filters:{query:state.query,area:state.area,priority:state.priority,types:[...state.types]}});save('dashboards',state.dashboards);$('#modal').close();render()}if(form.id==='connection-form'){if(OFFLINE)throw Error('Live sources are disabled in the offline edition.');let raw=String(fd.get('endpoint')).trim();if(raw.startsWith('/'))raw=new URL(raw,location.href).href;const url=C.safeURL(raw);if(!url)throw Error('Enter an absolute HTTP(S) source URL.');state.settings.endpoint=url;save('settings',state.settings);startPolling();toast('Connecting to the supplied incident source…')}if(form.id==='map-form'){if(OFFLINE)throw Error('Online map tokens are not used in the offline edition.');const token=String(fd.get('mapToken')).trim();if(token&&!token.startsWith('pk.'))throw Error('Use a public Mapbox token beginning pk.');state.mapToken=token;toast('Map token set for this session. Select Satellite on a map.')}}catch(err){toast(err.message)}});
function validateWorkspace(value){
 if(value==null)return {};
 if(typeof value!=='object'||Array.isArray(value))throw Error('Workspace must be an object.');
 const result={},text=(v,name,max)=>{if(typeof v!=='string'||v.length>max)throw Error(name+' must be text of at most '+max+' characters.');return v;};
 const ids=(v,name,max=5000)=>{if(!Array.isArray(v)||v.length>max)throw Error(name+' exceeds the '+max+'-item limit.');return [...new Set(v.map(x=>{text(x,name,120);if(!/^[a-zA-Z0-9][a-zA-Z0-9_.:-]*$/.test(x))throw Error(name+' contains an invalid identifier.');return x;}))]};
 const filters=v=>{if(!v||typeof v!=='object'||Array.isArray(v))throw Error('Dashboard / alert filters must be an object.');const priority=v.priority??'all';if(!['all','critical','high','moderate','low'].includes(priority))throw Error('Unsupported filter priority.');return {query:text(v.query??'','Filter query',500),area:text(v.area??'all','Filter area',180),priority,types:ids(v.types??[],'Event types',200)}};
 for(const key of ['favorites','feedFavorites','types'])if(Object.prototype.hasOwnProperty.call(value,key))result[key]=ids(value[key],key,key==='types'?200:5000);
 if(Object.prototype.hasOwnProperty.call(value,'dashboards')){if(!Array.isArray(value.dashboards)||value.dashboards.length>100)throw Error('At most 100 dashboards can be imported.');result.dashboards=value.dashboards.map(d=>{if(!d||typeof d!=='object'||Array.isArray(d))throw Error('Invalid dashboard.');return {name:text(d.name,'Dashboard name',80),filters:filters(d.filters)}});}
 if(Object.prototype.hasOwnProperty.call(value,'alerts')){if(!Array.isArray(value.alerts)||value.alerts.length>100)throw Error('At most 100 alert rules can be imported.');result.alerts=value.alerts.map(a=>{if(!a||typeof a!=='object'||Array.isArray(a))throw Error('Invalid alert.');return {name:text(a.name,'Alert name',80),...filters(a)}});}
 if(Object.prototype.hasOwnProperty.call(value,'geojson'))result.geojson=value.geojson===null?null:validateGeo(value.geojson);
 return result;
}
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('Import is limited to 10 MB.');const parsed=JSON.parse(await file.text()),validated=C.validateImport(parsed),workspace=validateWorkspace(parsed.workspace);const nextData={incidents:C.mergeById(data.incidents,validated.incidents),feeds:C.mergeById(data.feeds,validated.feeds),calls:C.mergeById(data.calls,validated.calls)};
 // Validate the complete transaction before stopping a connection or changing any in-memory state.
 invalidatePoll();state.settings.endpoint='';save('settings',state.settings);data=nextData;state.sourceMode='saved';state.lastSync=new Date().toISOString();sourceError='';
 for(const key of ['favorites','feedFavorites'])if(Object.prototype.hasOwnProperty.call(workspace,key)){state[key]=new Set(workspace[key]);save(key,workspace[key]);}
 for(const key of ['types','dashboards','alerts','geojson'])if(Object.prototype.hasOwnProperty.call(workspace,key)){state[key]=workspace[key];save(key,workspace[key]);}
 if(!data.incidents.some(i=>i.id===state.selected))state.selected=data.incidents[0]?.id;persistData();render();toast(`Imported ${validated.incidents.length} incidents, ${validated.feeds.length} feeds, ${validated.calls.length} calls. Existing IDs were updated; saved workspace preferences restored.`)}catch(err){toast('Import rejected: '+err.message)}e.target.value=''});
$('#geo-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>8*1024*1024)throw Error('GeoJSON is limited to 8 MB.');state.geojson=validateGeo(JSON.parse(await file.text()));save('geojson',state.geojson);state.mapMode='parcel';render();toast('Parcel geometry imported. Select an incident near its geographic extent.')}catch(err){toast('GeoJSON rejected: '+err.message)}e.target.value=''});
$('#audio-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>100*1024*1024)throw Error('Recordings are limited to 100 MB.');if(data.calls.length>=5000)throw Error('The workspace supports up to 5000 calls. Export and archive records before adding more.');const id='local-'+Date.now();await recordingPut(id,file);const blobURL=URL.createObjectURL(file);objectURLs.set(id,blobURL);if(!data.feeds.some(f=>f.id==='local-recordings'))data.feeds.push(C.normalizeFeed({id:'local-recordings',name:'Local recordings',area:'On this device',kind:'Archive',description:'Audio files imported by you.'}));const c=C.normalizeCall({id,feedId:'local-recordings',time:new Date().toISOString(),duration:0,transcript:'Local recording: '+file.name,source:'User imported audio file',demo:false});data.calls=C.mergeById([c],data.calls);persistData();playCall(id);toast('Recording saved on this device for offline playback.');if(state.view==='favorites')render()}catch(err){toast('Audio import failed: '+err.message)}e.target.value=''});
$('#player-toggle').onclick=()=>{if(audioCurrent?.kind==='speech'){if(speechSynthesis.speaking){speechSynthesis.cancel();$('#player-toggle').textContent='▶';$('#player-state').textContent='Stopped'}else speech(audioCurrent.utterance.text,audioCurrent.title);return}const a=$('#audio');a.paused?a.play().catch(()=>toast('Playback unavailable')):a.pause()};$('#player-prev').onclick=()=>nextCall(-1);$('#player-next').onclick=()=>nextCall(1);$('#player-close').onclick=()=>{stopAudio();audioCurrent=null;$('#mini-player').classList.add('hidden')};$('#volume').oninput=e=>$('#audio').volume=Number(e.target.value);
for(const [event,label]of [['playing','Playing audio'],['pause','Paused'],['waiting','Buffering…'],['stalled','Stream stalled'],['error','Audio source unavailable']])$('#audio').addEventListener(event,()=>{if(audioCurrent?.kind==='speech')return;$('#player-state').textContent=label;$('#player-toggle').textContent=event==='playing'?'Ⅱ':'▶'});
$('#audio').addEventListener('ended',()=>{$('#player-state').textContent='Recording finished';if(state.settings.continueAudio&&audioCurrent?.kind==='call')nextCall(1)});
function toggleFullscreen(){if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>toast('Full screen is not supported in this browser.'))}
$('#fullscreen').onclick=toggleFullscreen;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});window.addEventListener('hashchange',()=>{if(Object.hasOwn(titles,location.hash.slice(1))&&state.view!==location.hash.slice(1)){state.view=location.hash.slice(1);render()}});window.addEventListener('online',notifyBanner);window.addEventListener('offline',()=>{notifyBanner();render()});window.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modal').open)$('#modal').close()});
render();if(state.settings.endpoint)startPolling();if('serviceWorker'in navigator&&['http:','https:'].includes(location.protocol)&&!window.ATLAS_STANDALONE)navigator.serviceWorker.register('./sw.js').catch(()=>{});
window.AtlasApp={state,getData:()=>data,render,validateGeo,validateWorkspace,callQueue};
